inputs = ['diycc', 'jcugz', 'jzkg', 'ubzxxv', 'hg']
outputs = ['dihecc', 'biccugxu', 'bicxukg', 'uiecxuxxv', 'hg']

print("Input/Output pairs:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"  {i}: '{inp}' -> '{outp}'")

print("\nAnalyzing differences:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"  {i}: '{inp}' vs '{outp}'")
        # Find positions where they differ
        for j, (c1, c2) in enumerate(zip(inp, outp)):
            if c1 != c2:
                print(f"    position {j}: '{c1}' -> '{c2}'")
        if len(outp) > len(inp):
            print(f"    added {len(outp) - len(inp)} characters at end")
        elif len(inp) > len(outp):
            print(f"    removed {len(inp) - len(outp)} characters at end")

